from pathlib import Path
import json,geopandas as g,numpy as np,shapely
from shapely.strtree import STRtree
from pyproj import Transformer
out=Path('data/user_shanghai');new=g.read_file(out/'national_roads.gpkg').to_crs(32651);old=g.read_file('data/raw/osm/gis_osm_roads_free_1.shp').to_crs(32651);classes=['motorway','trunk','primary','secondary','tertiary','residential','unclassified','service','living_street'];new=new[new.fclass.isin(classes)&(new.bridge!='T')&(new.tunnel!='T')&(new.layer.fillna(0)==0)];old=old[old.fclass.isin(classes)&(old.bridge!='T')&(old.tunnel!='T')&(old.layer.fillna(0)==0)];city=g.read_file('data/raw/shanghai_boundary.geojson').to_crs(32651).geometry.union_all();shapely.prepare(city);new=new[shapely.intersects(city,new.geometry.array)];old=old[shapely.intersects(city,old.geometry.array)];ng=new.geometry.to_numpy();og=old.geometry.to_numpy();tree=STRtree(og);pts=shapely.line_interpolate_point(ng,.5,normalized=True);idx,d=tree.query_nearest(pts,return_distance=True,all_matches=False);lens=shapely.length(ng);print('national roads',len(new),'2026 roads',len(old),'midpoint distance',np.percentile(d,[50,75,90,95,99]).tolist(),flush=True);print('national length m',lens.sum(),'shares within 2m',lens[d<2].sum()/lens.sum(),'10m',lens[d<10].sum()/lens.sum(),'30m',lens[d<30].sum()/lens.sum(),flush=True)
reverse=STRtree(ng);op=shapely.line_interpolate_point(og,.5,normalized=True);_,dd=reverse.query_nearest(op,return_distance=True,all_matches=False);ol=shapely.length(og);print('old length shares 2m 10m 30m',float(ol[dd<2].sum()/ol.sum()),float(ol[dd<10].sum()/ol.sum()),float(ol[dd<30].sum()/ol.sum()),flush=True)
metrics={'new_roads':len(new),'old_roads':len(old),'new_midpoint_distance_p50_p75_p90_p95_p99_m':np.percentile(d,[50,75,90,95,99]).tolist(),'new_length_share_midpoint_within_2m':float(lens[d<2].sum()/lens.sum()),'new_length_share_midpoint_within_10m':float(lens[d<10].sum()/lens.sum()),'new_length_share_midpoint_within_30m':float(lens[d<30].sum()/lens.sum()),'old_length_share_midpoint_within_2m':float(ol[dd<2].sum()/ol.sum()),'old_length_share_midpoint_within_10m':float(ol[dd<10].sum()/ol.sum()),'old_length_share_midpoint_within_30m':float(ol[dd<30].sum()/ol.sum())};(out/'road_comparison.json').write_text(json.dumps(metrics,indent=2));
# Water line QA: distances to mapped OSM centerlines / polygon water, as coarse context, not exact cartographic validation.
osmw=g.read_file('data/raw/osm/gis_osm_waterways_free_1.shp').to_crs(32651);wt=STRtree(osmw.geometry.to_numpy());
for fp in sorted(out.glob('我国*河流.shp.gpkg')):
 v=g.read_file(fp).to_crs(32651);w=shapely.line_interpolate_point(v.geometry.array,.5,normalized=True);_,dv=wt.query_nearest(w,return_distance=True,all_matches=False);print(fp.name,'features',len(v),'distance to OSM water line midpoint median m',float(np.median(dv)),'p90',float(np.quantile(dv,.9)),flush=True)
